void testIdentity() {
  const uint8_t mac[6] = {0x80, 0xb5, 0x4e, 0xcf, 0x49, 0x40};
  char huid[pixc::kHuidLen + 1];
  pixc::huidFromMac(mac, huid, sizeof(huid));
  CHECK(std::strcmp(huid, "EPX-80B54ECF4940") == 0);
  char hex[13];
  pixc::macHex(mac, hex, sizeof(hex));
  CHECK(std::strcmp(hex, "80b54ecf4940") == 0);
  char small[8] = "x";
  pixc::huidFromMac(mac, small, sizeof(small));   // too small: empty, never cut
  CHECK(small[0] == 0);

  CHECK(pixc::validHuid("EPX-80B54ECF4940"));
  CHECK(!pixc::validHuid("EPX-80b54ecf4940"));     // upper case only, as the Writer writes it
  CHECK(!pixc::validHuid("EPX-80B54ECF494"));
  CHECK(!pixc::validHuid("EPX-80B54ECF49400"));
  CHECK(!pixc::validHuid("epx-80B54ECF4940"));
  CHECK(!pixc::validHuid("EPX80B54ECF49400"));
  CHECK(!pixc::validHuid("EPX-80B54ECF494G"));
  CHECK(!pixc::validHuid(""));
  CHECK(!pixc::validHuid(nullptr));

  CHECK(pixc::validHwRev("H01-E1"));
  CHECK(pixc::validHwRev("H99-Z0"));
  CHECK(!pixc::validHwRev("H1-E1"));
  CHECK(!pixc::validHwRev("H01-e1"));
  CHECK(!pixc::validHwRev("H01E1"));
  CHECK(!pixc::validHwRev("H01-E12"));
  CHECK(!pixc::validHwRev("h01-E1"));
  CHECK(!pixc::validHwRev("H01-11"));
  CHECK(!pixc::validHwRev(""));
  CHECK(!pixc::validHwRev(nullptr));

  CHECK(pixc::huidMatchesMac("EPX-80B54ECF4940", mac));
  const uint8_t other[6] = {0x80, 0xb5, 0x4e, 0xcf, 0x49, 0x41};
  CHECK(!pixc::huidMatchesMac("EPX-80B54ECF4940", other));   // factory data copied from another board
  CHECK(!pixc::huidMatchesMac("EPX-80b54ecf4940", mac));
  CHECK(!pixc::huidMatchesMac(nullptr, mac));
  CHECK(!pixc::huidMatchesMac("EPX-80B54ECF4940", nullptr));
}

std::string feedAll(pixc::LineReader& r, const char* bytes, int* lines) {
  std::string last;
  for (const char* p = bytes; *p; p++) {
    if (r.feed(static_cast<uint8_t>(*p))) { last = r.line(); if (lines) (*lines)++; }
  }
  return last;
}

void testLineReader() {
  pixc::LineReader r;
  int n = 0;
  CHECK(feedAll(r, "pixc info\n", &n) == "pixc info" && n == 1);
  CHECK(std::strcmp(r.line(), "pixc info") == 0);        // kept until the next byte
  n = 0;
  CHECK(feedAll(r, "pixc runcheck\r\n", &n) == "pixc runcheck" && n == 1);   // CRLF: one line
  n = 0;
  feedAll(r, "\n\r\n\n", &n);
  CHECK(n == 0);                                          // empty lines are no lines
  // A line one byte longer than the limit is dropped whole; the next line is read normally.
  std::string longLine(pixc::kSerialLineMax + 1, 'a');
  longLine += "\npixc info\n";
  n = 0;
  CHECK(feedAll(r, longLine.c_str(), &n) == "pixc info" && n == 1);
  std::string exact(pixc::kSerialLineMax, 'b');
  exact += "\n";
  n = 0;
  CHECK(feedAll(r, exact.c_str(), &n).size() == pixc::kSerialLineMax && n == 1);
  // Boot noise or another protocol's byte spoils its line.
  n = 0;
  CHECK(feedAll(r, "\x01pixc info\npixc download\n", &n) == "pixc download" && n == 1);
  n = 0;
  const char noise[] = {'p', 'i', 'x', 'c', ' ', 'i', 'n', 'f', 'o', static_cast<char>(0xC9), '\n', 0};
  feedAll(r, noise, &n);
  CHECK(n == 0);
  r.reset();
  CHECK(std::strcmp(r.line(), "") == 0);
}

void testParseCommand() {
  using pixc::SerialCmd;
  const char* arg = nullptr;
  size_t len = 99;
  CHECK(pixc::parseSerialCommand("pixc info", &arg, &len) == SerialCmd::Info && len == 0);
  CHECK(pixc::parseSerialCommand("pixc runcheck", &arg, &len) == SerialCmd::Runcheck);
  CHECK(pixc::parseSerialCommand("pixc download", &arg, &len) == SerialCmd::Download);
  CHECK(pixc::parseSerialCommand("pixc   info  ", &arg, &len) == SerialCmd::Info);
  CHECK(pixc::parseSerialCommand("pixc otacheck status", &arg, &len) == SerialCmd::OtacheckStatus);
  CHECK(pixc::parseSerialCommand("pixc otacheck status ", &arg, &len) == SerialCmd::OtacheckStatus);
  CHECK(pixc::parseSerialCommand("pixc otacheck MEUCIQ==", &arg, &len) == SerialCmd::Otacheck);
  CHECK(len == 8 && std::strncmp(arg, "MEUCIQ==", len) == 0);
  CHECK(pixc::parseSerialCommand("pixc otacheck MEUCIQ==   ", &arg, &len) == SerialCmd::Otacheck && len == 8);
  CHECK(pixc::parseSerialCommand("pixc otacheck", &arg, &len) == SerialCmd::Otacheck && len == 0);
  CHECK(pixc::parseSerialCommand("pixc otacheck a b", &arg, &len) == SerialCmd::Unknown);
  CHECK(pixc::parseSerialCommand("pixc otacheck statusx", &arg, &len) == SerialCmd::Otacheck);
  // Unknown: answered with {"error":"unknown command"}.
  CHECK(pixc::parseSerialCommand("pixc", &arg, &len) == SerialCmd::Unknown);
  CHECK(pixc::parseSerialCommand("pixc ", &arg, &len) == SerialCmd::Unknown);
  CHECK(pixc::parseSerialCommand("pixc reboot", &arg, &len) == SerialCmd::Unknown);
  CHECK(pixc::parseSerialCommand("pixc info now", &arg, &len) == SerialCmd::Unknown);
  CHECK(pixc::parseSerialCommand("pixc INFO", &arg, &len) == SerialCmd::Unknown);
  CHECK(pixc::parseSerialCommand("pixc infos", &arg, &len) == SerialCmd::Unknown);
  CHECK(pixc::parseSerialCommand("pixc runcheck x", &arg, &len) == SerialCmd::Unknown);
  CHECK(pixc::parseSerialCommand("pixc download now", &arg, &len) == SerialCmd::Unknown);
  // Not ours: no answer at all.
  CHECK(pixc::parseSerialCommand("pixcinfo", &arg, &len) == SerialCmd::NotPixc);
  CHECK(pixc::parseSerialCommand(" pixc info", &arg, &len) == SerialCmd::NotPixc);
  CHECK(pixc::parseSerialCommand("PIXC info", &arg, &len) == SerialCmd::NotPixc);
  CHECK(pixc::parseSerialCommand("pix", &arg, &len) == SerialCmd::NotPixc);
  CHECK(pixc::parseSerialCommand("", &arg, &len) == SerialCmd::NotPixc);
  CHECK(pixc::parseSerialCommand(nullptr, &arg, &len) == SerialCmd::NotPixc);
  CHECK(pixc::parseSerialCommand("pixc {\"check\":\"led\"}", &arg, &len) == SerialCmd::Unknown);   // an answer echoed back

  // Ten minutes after a boot with Wi-Fi configured, nothing is read.
  CHECK(pixc::serialCommandsOpen(0, true));
  CHECK(pixc::serialCommandsOpen(pixc::kSerialWindowMs - 1, true));
  CHECK(!pixc::serialCommandsOpen(pixc::kSerialWindowMs, true));
  CHECK(!pixc::serialCommandsOpen(0xFFFFFFFFu, true));
  CHECK(pixc::serialCommandsOpen(pixc::kSerialWindowMs, false));
  CHECK(pixc::serialCommandsOpen(0xFFFFFFFFu, false));
  CHECK(pixc::kSerialWindowMs == 600000);
}

std::string b64(const uint8_t* d, size_t n) {
  static const char* A = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  std::string s;
  for (size_t i = 0; i < n; i += 3) {
    const uint32_t v = (d[i] << 16) | ((i + 1 < n ? d[i + 1] : 0) << 8) | (i + 2 < n ? d[i + 2] : 0);
    s += A[(v >> 18) & 63];
    s += A[(v >> 12) & 63];
    s += i + 1 < n ? A[(v >> 6) & 63] : '=';
    s += i + 2 < n ? A[v & 63] : '=';
  }
  return s;
}

int dec(const char* s, uint8_t* out, size_t cap) { return pixc::base64Decode(s, std::strlen(s), out, cap); }

void testBase64() {
  uint8_t out[80];
  // RFC 4648, section 10.
  CHECK(dec("", out, sizeof(out)) == 0);
  CHECK(dec("Zg==", out, sizeof(out)) == 1 && out[0] == 'f');
  CHECK(dec("Zm8=", out, sizeof(out)) == 2 && std::memcmp(out, "fo", 2) == 0);
  CHECK(dec("Zm9v", out, sizeof(out)) == 3 && std::memcmp(out, "foo", 3) == 0);
  CHECK(dec("Zm9vYg==", out, sizeof(out)) == 4 && std::memcmp(out, "foob", 4) == 0);
  CHECK(dec("Zm9vYmE=", out, sizeof(out)) == 5 && std::memcmp(out, "fooba", 5) == 0);
  CHECK(dec("Zm9vYmFy", out, sizeof(out)) == 6 && std::memcmp(out, "foobar", 6) == 0);
  // Padding optional.
  CHECK(dec("Zg", out, sizeof(out)) == 1 && out[0] == 'f');
  CHECK(dec("Zm9vYmE", out, sizeof(out)) == 5);
  // Malformed.
  CHECK(dec("Z", out, sizeof(out)) == -1);
  CHECK(dec("Zm9vY", out, sizeof(out)) == -1);
  CHECK(dec("Zg=", out, sizeof(out)) == -1);
  CHECK(dec("Zg===", out, sizeof(out)) == -1);
  CHECK(dec("Z=g=", out, sizeof(out)) == -1);
  CHECK(dec("Zm9v Yg==", out, sizeof(out)) == -1);
  CHECK(dec("Zm9v\nYg==", out, sizeof(out)) == -1);
  CHECK(dec("Zm9-", out, sizeof(out)) == -1);           // base64url is not accepted
  CHECK(dec("Zm9_", out, sizeof(out)) == -1);
  CHECK(pixc::base64Decode(nullptr, 4, out, sizeof(out)) == -1);
  CHECK(dec("Zm9vYmFy", out, 5) == -1);                  // longer than the buffer
  CHECK(dec("Zm9vYmFy", out, 6) == 6);
  // `n` bounds the input: the argument of a command line.
  CHECK(pixc::base64Decode("Zm9vYmFy trailing", 8, out, sizeof(out)) == 6);
  // A P-256 signature's DER (70-72 bytes) round-trips at every length it can have.
  for (size_t len = 68; len <= 72; len++) {
    uint8_t sig[72];
    for (size_t i = 0; i < len; i++) sig[i] = static_cast<uint8_t>(i * 37 + len);
    const std::string s = b64(sig, len);
    CHECK(s.size() <= 96);
    std::string line = "pixc otacheck " + s;
    CHECK(line.size() <= pixc::kSerialLineMax);
    const char* arg = nullptr;
    size_t argLen = 0;
    CHECK(pixc::parseSerialCommand(line.c_str(), &arg, &argLen) == pixc::SerialCmd::Otacheck);
    CHECK(pixc::base64Decode(arg, argLen, out, sizeof(out)) == static_cast<int>(len));
    CHECK(std::memcmp(out, sig, len) == 0);
  }
}

void testVerdicts() {
  CHECK(pixc::wifiScanPasses(1, -60));
  CHECK(pixc::wifiScanPasses(12, -95));
  CHECK(pixc::wifiScanPasses(3, -10));
  CHECK(!pixc::wifiScanPasses(0, -60));
  CHECK(!pixc::wifiScanPasses(3, -96));
  CHECK(!pixc::wifiScanPasses(3, -9));
  CHECK(!pixc::wifiScanPasses(3, 0));
  CHECK(!pixc::wifiScanPasses(-2, -60));                 // WIFI_SCAN_FAILED

  CHECK(pixc::ledFpsPasses(60.0f));
  CHECK(pixc::ledFpsPasses(107.5f));
  CHECK(!pixc::ledFpsPasses(59.9f));
  CHECK(!pixc::ledFpsPasses(0.0f));
  CHECK(!pixc::ledFpsPasses(2000.0f));                   // returned without sending: nothing on the wire
  // A 300-LED WS2812 frame (9.0 ms on the wire, 300 us reset) cannot beat the ceiling, and a working
  // output at the wire's speed passes.
  const float wire = pixc::framesPerSecond(60, 60 * (pixc::kTestLeds * 24 * 125 / 100 + 300));
  CHECK(wire > 100.0f && wire < 112.0f && pixc::ledFpsPasses(wire));
  CHECK(pixc::framesPerSecond(60, 0) == 0.0f);
  CHECK(pixc::framesPerSecond(60, 1000000) == 60.0f);
}

// Runs the button through a timeline: the level (pressed) from `from` to `to`, a tick every `step` ms.
struct ButtonRun {
  pixc::BootButton b;
  int amber = 0, cancel = 0, reset = 0;
  uint32_t lastEventAt = 0;
  pixc::ButtonEvent last = pixc::ButtonEvent::None;
  void run(uint32_t from, uint32_t to, bool pressed, uint32_t step = 10) {
    for (uint32_t t = from; t < to; t += step) {
      const pixc::ButtonEvent e = b.tick(t, pressed);
      if (e == pixc::ButtonEvent::None) continue;
      last = e;
      lastEventAt = t;
      if (e == pixc::ButtonEvent::Amber) amber++;
      if (e == pixc::ButtonEvent::Cancel) cancel++;
      if (e == pixc::ButtonEvent::Reset) reset++;
    }
  }
};

void testBootButton() {
  using pixc::ButtonEvent;
  {  // Held 12 s and released: amber at 10 s, then the reset on release.
    ButtonRun r;
    r.run(0, 3000, false);
    r.run(3000, 15000, true);
    CHECK(r.amber == 1 && r.reset == 0);
    CHECK(r.last == ButtonEvent::Amber && r.lastEventAt >= 13000 && r.lastEventAt < 13020);
    r.run(15000, 16000, false);
    CHECK(r.reset == 1 && r.cancel == 0 && r.lastEventAt < 15100);
    r.run(16000, 60000, true);                           // the reset is under way: nothing more
    CHECK(r.amber == 1 && r.reset == 1);
  }
  {  // A short press does nothing; the next long one still works.
    ButtonRun r;
    r.run(0, 3000, false);
    r.run(3000, 12999, true);
    r.run(12999, 14000, false);
    CHECK(r.amber == 0 && r.reset == 0);
    r.run(14000, 24100, true);
    CHECK(r.amber == 1);
    r.run(24100, 25000, false);
    CHECK(r.reset == 1);
  }
  {  // Held 30 s or more: the amber ends and nothing is wiped, on release or after.
    ButtonRun r;
    r.run(0, 3000, false);
    r.run(3000, 45000, true);
    CHECK(r.amber == 1 && r.cancel == 1 && r.reset == 0);
    CHECK(r.last == ButtonEvent::Cancel && r.lastEventAt >= 33000 && r.lastEventAt < 33020);
    r.run(45000, 46000, false);
    CHECK(r.reset == 0 && r.cancel == 1);
    r.run(46000, 58000, true);                           // a fresh press afterwards counts again
    r.run(58000, 59000, false);
    CHECK(r.amber == 2 && r.reset == 1);
  }
  {  // Released just before 30 s resets; at 30 s it is already ignored.
    ButtonRun a;
    a.run(0, 3000, false);
    a.run(3000, 32990, true);
    a.run(32990, 34000, false);
    CHECK(a.reset == 1 && a.cancel == 0);
    ButtonRun b;
    b.run(0, 3000, false);
    b.run(3000, 33000, true);
    b.run(33000, 34000, false);
    CHECK(b.reset == 0 && b.cancel == 1);
  }
  {  // Low from boot (button held, or DTR asserted through a software restart): never a press until
     // the pin has been seen high after the first 2 s.
    ButtonRun r;
    r.run(0, 60000, true);
    CHECK(r.amber == 0 && r.reset == 0 && r.cancel == 0);
    r.run(60000, 61000, false);
    r.run(61000, 72000, true);
    r.run(72000, 73000, false);
    CHECK(r.amber == 1 && r.reset == 1);
  }
  {  // Not read in the first 2 s: a press that starts then and lasts past 12 s is not a press.
    ButtonRun r;
    r.run(0, 500, false);
    r.run(500, 14000, true);
    r.run(14000, 15000, false);
    CHECK(r.amber == 0 && r.reset == 0);
  }
  {  // Contact bounce during the hold (high for 20 ms now and then) does not end it.
    ButtonRun r;
    r.run(0, 3000, false);
    uint32_t t = 3000;
    while (t < 15000) {
      r.run(t, t + 980, true);
      r.run(t + 980, t + 1000, false);
      t += 1000;
    }
    CHECK(r.amber == 1 && r.reset == 0);
    r.run(15000, 16000, false);
    CHECK(r.reset == 1);
  }
  {  // A glitch low shorter than the debounce is no press at all.
    ButtonRun r;
    r.run(0, 3000, false);
    for (uint32_t t = 3000; t < 40000; t += 500) {
      r.run(t, t + 40, true);
      r.run(t + 40, t + 500, false);
    }
    CHECK(r.amber == 0 && r.reset == 0 && r.cancel == 0);
  }
  {  // A slow loop (one tick a second) still times the hold from the press.
    ButtonRun r;
    r.run(0, 3000, false, 1000);
    r.run(3000, 14000, true, 1000);
    CHECK(r.amber == 1);
    r.run(14000, 16000, false, 1000);
    CHECK(r.reset == 1);
  }
}

bool validJson(const char* s) {
  DynamicJsonDocument doc(1024);
  return !deserializeJson(doc, s) && doc.is<JsonObject>();
}

void testOtaCheck() {
  using pixc::OtaBootAction;
  using pixc::OtaPhase;
  using pixc::OtaStep;
  const auto started = [] {
    pixc::OtaCheckState s;
    s.signature = OtaStep::Ok;
    s.copy = OtaStep::Ok;
    s.phase = OtaPhase::BootSpare;
    std::strcpy(s.orig, "app0");
    std::strcpy(s.spare, "app1");
    return s;
  };
  char buf[512];

  {  // The whole way: spare starts, returns, the original reports done.
    pixc::OtaCheckState s = started();
    CHECK(pixc::otaCheckOnBoot(s, "app1") == OtaBootAction::ReturnFromSpare);
    CHECK(s.phase == OtaPhase::Back && s.bootSpare == OtaStep::Ok);
    CHECK(pixc::otaCheckOnBoot(s, "app0") == OtaBootAction::Report);
    CHECK(s.phase == OtaPhase::Done && s.back == OtaStep::Ok && s.ok());
    CHECK(pixc::formatOtaCheckDone(buf, sizeof(buf), s) > 0);
    CHECK(std::strcmp(buf, "{\"otacheck\":\"done\",\"ok\":true,\"steps\":{\"signature\":true,\"copy\":true,"
                           "\"boot_spare\":true,\"back\":true}}") == 0);
    CHECK(validJson(buf));
    // Done stays done: a later boot does nothing about it.
    CHECK(pixc::otaCheckOnBoot(s, "app0") == OtaBootAction::None);
    CHECK(pixc::otaCheckOnBoot(s, "app1") == OtaBootAction::None);
  }
  {  // The spare never ran its loop (the bootloader went back to the original): boot_spare failed.
    pixc::OtaCheckState s = started();
    CHECK(pixc::otaCheckOnBoot(s, "app0") == OtaBootAction::Report);
    CHECK(s.phase == OtaPhase::Done && s.bootSpare == OtaStep::Fail && s.back == OtaStep::NotRun && !s.ok());
    CHECK(pixc::formatOtaCheckDone(buf, sizeof(buf), s) > 0);
    CHECK(std::strcmp(buf, "{\"otacheck\":\"done\",\"ok\":false,\"steps\":{\"signature\":true,\"copy\":true,"
                           "\"boot_spare\":false,\"back\":null},\"error\":\"the spare slot did not start\"}") == 0);
    CHECK(validJson(buf));
  }
  {  // The return from the spare failed: one ordinary set-boot return, then success...
    pixc::OtaCheckState s = started();
    CHECK(pixc::otaCheckOnBoot(s, "app1") == OtaBootAction::ReturnFromSpare);
    CHECK(pixc::otaCheckOnBoot(s, "app1") == OtaBootAction::SetBootOriginal);
    CHECK(s.phase == OtaPhase::Back && s.returns == 1);
    CHECK(pixc::otaCheckOnBoot(s, "app0") == OtaBootAction::Report && s.ok());
  }
  {  // ...or, a second time on the spare, back failed: never a third restart.
    pixc::OtaCheckState s = started();
    pixc::otaCheckOnBoot(s, "app1");
    pixc::otaCheckOnBoot(s, "app1");
    CHECK(pixc::otaCheckOnBoot(s, "app1") == OtaBootAction::Report);
    CHECK(s.phase == OtaPhase::Done && s.back == OtaStep::Fail && !s.ok());
    CHECK(std::strcmp(s.error, "still on the spare slot") == 0);
    CHECK(pixc::otaCheckOnBoot(s, "app1") == OtaBootAction::None);
  }
  {  // A slot that is neither.
    pixc::OtaCheckState s = started();
    CHECK(pixc::otaCheckOnBoot(s, "factory") == OtaBootAction::Report && !s.ok());
    pixc::OtaCheckState t = started();
    CHECK(pixc::otaCheckOnBoot(t, nullptr) == OtaBootAction::Report && !t.ok());
  }
  {  // Nothing started: nothing to do at boot.
    pixc::OtaCheckState s;
    CHECK(pixc::otaCheckOnBoot(s, "app0") == OtaBootAction::None);
    CHECK(s.phase == OtaPhase::None);
  }
  {  // A failure before any restart (the signature): the steps after it are null.
    pixc::OtaCheckState s;
    s.signature = OtaStep::Fail;
    s.fail("signature mismatch");
    CHECK(pixc::formatOtaCheckDone(buf, sizeof(buf), s) > 0);
    CHECK(std::strcmp(buf, "{\"otacheck\":\"done\",\"ok\":false,\"steps\":{\"signature\":false,\"copy\":null,"
                           "\"boot_spare\":null,\"back\":null},\"error\":\"signature mismatch\"}") == 0);
    // The first reason is kept; the error is escaped and bounded.
    s.fail("later");
    CHECK(std::strcmp(s.error, "signature mismatch") == 0);
    pixc::OtaCheckState q;
    q.fail("a \"quoted\" \\ reason that is much longer than the forty-seven characters kept");
    CHECK(std::strlen(q.error) == pixc::kOtaErrorMax);
    CHECK(pixc::formatOtaCheckDone(buf, sizeof(buf), q) > 0 && validJson(buf));
  }
  {  // Too small a buffer prints nothing rather than a cut line.
    pixc::OtaCheckState s;
    CHECK(pixc::formatOtaCheckDone(buf, 40, s) == 0 && buf[0] == 0);
  }
  {  // A state read back from flash: only what this code writes is used, and strings end in range.
    pixc::OtaCheckState s = started();
    CHECK(pixc::otaCheckStateValid(s));
    pixc::OtaCheckState bad = s;
    bad.version = 2;
    CHECK(!pixc::otaCheckStateValid(bad));
    bad = s;
    bad.phase = static_cast<OtaPhase>(7);
    CHECK(!pixc::otaCheckStateValid(bad));
    bad = s;
    bad.back = static_cast<OtaStep>(5);
    CHECK(!pixc::otaCheckStateValid(bad));
    bad = s;
    bad.returns = 9;
    CHECK(!pixc::otaCheckStateValid(bad));
    bad = s;
    std::memset(bad.orig, 'x', sizeof(bad.orig));
    std::memset(bad.error, 'y', sizeof(bad.error));
    CHECK(pixc::otaCheckStateValid(bad));
    CHECK(std::strlen(bad.orig) == pixc::kOtaLabelMax && std::strlen(bad.error) == pixc::kOtaErrorMax);
    pixc::OtaCheckState blank;   // erased flash reads as 0xFF
    std::memset(static_cast<void*>(&blank), 0xFF, sizeof(blank));
    CHECK(!pixc::otaCheckStateValid(blank));
  }
}

